<template>
  <div id="header">
    <b-navbar>
      <b-nav tabs>
        <b-nav-item disabled>
          <b>{{ appVersion }}</b>
        </b-nav-item>
        <b-nav-item to="/" exact exact-active-class="active">Dashboard</b-nav-item>
        <b-nav-item to="/hosts" exact exact-active-class="active">Hosts</b-nav-item>
      </b-nav>
    </b-navbar>
  </div>
</template>

<script>
export default {
  name: "Header",
  props: {
    stompClient: Object
  },
  data() {
    return {
      appVersion: "---"
    };
  },
  methods: {
    send() {
      if (this.stompClient && this.stompClient.connected) {
        console.log("Request version");
        // const msg = { name: this.send_message };
        // console.log(JSON.stringify(msg));
        // this.stompClient.send("/jormanager/version", JSON.stringify(msg))
        this.stompClient.send("/jormanager/version");
      }
    }
  },
  mounted() {
    this.stompClient.subscribe("/topic/version", tick => {
      console.log(tick);
      this.appVersion = JSON.parse(tick.body).data;
    });
    // request the version
    this.send();
  }
};
</script>

