<template>
  <div id="app" v-if="connected">
    <Header :stompClient="stompClient" />
    <b-container>
      <router-view />
    </b-container>
  </div>
</template>

<script>
import SockJS from "sockjs-client";
import Stomp from "webstomp-client";
import Header from "@/components/Header";
// import Body from "@/components/Body";

export default {
  name: "App",
  data() {
    return {
      stompClient: null,
      socket: null,
      connected: false,
      appVersion: null
    };
  },
  methods: {
    connect() {
      this.socket = new SockJS(this.websocketUrl);
      this.stompClient = Stomp.over(this.socket, {
        debug: true
      });
      this.stompClient.connect(
        {},
        frame => {
          this.connected = true;
          console.log(frame);
        },
        error => {
          console.log(error);
          this.connected = false;
        }
      );
    }
  },
  computed: {
    websocketUrl() {
      if (window.webpackHotUpdate) {
        // debug mode
        return "http://localhost:8787/jormanager-websocket";
      } else {
        // release mode
        return "/jormanager-websocket";
      }
    }
  },
  mounted() {
    console.log("mounted()");
    this.connect();
  },
  components: {
    Header
    // Body
  }
};
</script>

